// Tiles are 51x120 pixels (virtual screen is 512x360)
constexpr size_t TILE_W_PIXELS = 51;
constexpr size_t TILE_H_PIXELS = 120;

constexpr uint32_t RESOURCE_TYPE_LEVL = 0x4C45564C;
constexpr uint32_t RESOURCE_TYPE_SHAP = 0x53484150;
constexpr uint32_t RESOURCE_TYPE_CUST = 0x43555354;
constexpr uint32_t RESOURCE_TYPE_PIEC = 0x50494543;

enum class TileType : uint16_t {
  EMPTY = 0x0000,
  FLOOR = 0x0001,
  SPIKES = 0x0002,
  SMALL_PILLAR = 0x0003,
  GATE = 0x0004,
  RAISE_TILE = 0x0005,
  DROP_TILE = 0x0006,
  TUNNEL = 0x0007,
  LARGE_PILLAR_BOTTOM = 0x0008,
  LARGE_PILLAR_TOP = 0x0009,
  POTION = 0x000A,
  LOOSE_FLOOR = 0x000B,
  SCYTHE_LEFT = 0x000C,
  SCYTHE_RIGHT = 0x000D,
  DEBRIS = 0x000E,
  SUPER_LOOSE_FLOOR = 0x000F,
  LEVEL_DOOR_LEFT = 0x0010,
  LEVEL_DOOR_RIGHT = 0x0011,
  CARPET = 0x0012,
  TORCH = 0x0013,
  WALL = 0x0014,
  SKELETON = 0x0015,
  SWORD = 0x0016,
  LAVA_LEFT = 0x0017,
  LAVA_RIGHT = 0x0018,
  HORIZONTAL_CRUSHER = 0x0019,
  TRAP_DOOR = 0x001A,
  CARPET_GATE = 0x001B,
  DESERT_ROCKS = 0x001C,
  DESERT_PLANKS = 0x001D,
  DESERT_QUICKSAND_STONE = 0x001E,
  TORCH_WITH_DEBRIS = 0x0020,
  DART_GUN = 0x0021,
  PRESSURE_PLATE = 0x0022,
  FLAME = 0x002B,
  BRIDGE = 0x002C,
  DOCK_PILLAR = 0x002F,
  SHIP = 0x0030,
  WINDOW = 0x0031,
};

bool is_space_tile(TileType tt) {
  return ((tt == TileType::EMPTY) ||
      (tt == TileType::LARGE_PILLAR_TOP) ||
      (tt == TileType::CARPET_GATE) ||
      (tt == TileType::DOCK_PILLAR) ||
      (tt == TileType::WINDOW));
}

