  //   0007 0168 0046 0000 0010 0000 0000 0000 0000 0000 0000 0000 0001 0000 0000 0000
  //
  // WHAT--------------- RES#: PPPP YYYY CCCC ???? ???? ???? ???? ???? ---- ---- ---- ---- ---- ---- KKKK
  // Temple altar        4075: 0020 0FEB 0011 0000 FFFF FFFF 0000 0000 0000 0000 0000 0000 0000 0000 0011
  //   IIII BBBB LLLL TTTT UUUU ---- ---- ---- ---- ---- ???? ???? ???? ???? ???? ????
  //   0000 016D 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000
