std::unordered_map<uint16_t, std::unique_ptr<LevelKind>> load_level_kinds(const std::string& data_dir) {
  // TODO: We'll need some stuff from Prince.rsrc too, for e.g. potions. Maybe make this a real class when that's implemented
  // TODO: CTBL is incorrect for the 253xx SHAPs in Caverns; find the right one
  std::unordered_map<uint16_t, std::unique_ptr<LevelKind>> ret;
  ret.emplace(1, std::make_unique<DesertLevelKind>(data_dir + "/Desert.rsrc"));
  ret.emplace(2, std::make_unique<TempleLevelKind>(data_dir + "/Temple.rsrc"));
  ret.emplace(3, std::make_unique<CavernsLevelKind>(data_dir + "/Caverns.rsrc"));
  ret.emplace(4, std::make_unique<RuinsLevelKind>(data_dir + "/Ruins.rsrc"));
  ret.emplace(5, std::make_unique<RooftopsLevelKind>(data_dir + "/Rooftops.rsrc"));
  ret.emplace(6, std::make_unique<FinalLevelKind>(data_dir + "/Final.rsrc"));
  return ret;
}

struct RoomGraph {
  struct Component {
    uint8_t component_id;
    std::unordered_map<uint8_t, std::pair<int8_t, int8_t>> placement_map;
  };

  const PrinceOfPersia2Level* level;
  std::vector<Component> components;
  std::unordered_map<uint32_t, uint8_t> room_id_for_placement;

  uint32_t remaining_room_ids = 0xFFFFFFFF;

  static uint32_t placement_key(uint8_t component_id, int8_t x, int8_t y) {
    return (component_id << 16) | (static_cast<uint8_t>(x) << 8) | static_cast<uint8_t>(y);
  }

  bool room_is_remaining(uint8_t room_id) const {
    return this->remaining_room_ids & (1 << room_id);
  }
  void mark_room_done(uint8_t room_id) {
    this->remaining_room_ids &= ~(1 << room_id);
  }

  void place_room(Component& component, uint8_t room_id, int8_t x, int8_t y) {
    uint32_t placement_key = this->placement_key(component.component_id, x, y);

    if (this->room_is_remaining(room_id)) {
      this->mark_room_done(room_id);

      component.placement_map.emplace(room_id, std::make_pair(x, y));
      this->room_id_for_placement.emplace(placement_key, room_id);

      const auto& links = this->level->room_links[room_id];
      if (links.left) {
        this->place_room(component, links.left - 1, x - 1, y);
      }
      if (links.right) {
        this->place_room(component, links.right - 1, x + 1, y);
      }
      if (links.above) {
        this->place_room(component, links.above - 1, x, y - 1);
      }
      if (links.below) {
        this->place_room(component, links.below - 1, x, y + 1);
      }

    } else {
      // If the room was already placed, ensure the room's existing placement matches the one we're supposed to add
      auto it = this->room_id_for_placement.find(placement_key);
      if (it == this->room_id_for_placement.end() || it->second != room_id) {
        phosg::log_warning_f("Warning: bad backlink at room {}", room_id);
      }
    }
  }

  void place_component(uint8_t start_room_id) {
    auto& component = this->components.emplace_back();
    component.component_id = this->components.size() - 1;
    this->place_room(component, start_room_id, 0, 0);
    if (component.placement_map.empty()) {
      components.pop_back(); // Room was already placed in another component
    } else {
      // Make all offsets nonnegative
      int16_t delta_x = 0, delta_y = 0;
      for (const auto& it : component.placement_map) {
        if (it.second.first < delta_x) {
          delta_x = it.second.first;
        }
        if (it.second.second < delta_y) {
          delta_y = it.second.second;
        }
      }
      for (auto& [room_id, placement] : component.placement_map) {
        this->room_id_for_placement.erase(this->placement_key(component.component_id, placement.first, placement.second));
        placement.first -= delta_x;
        placement.second -= delta_y;
        this->room_id_for_placement.emplace(this->placement_key(component.component_id, placement.first, placement.second), room_id);
      }
    }
  };

  RoomGraph(const PrinceOfPersia2Level* level) : level(level) {
    for (uint8_t room_id = 0; room_id < 32; room_id++) {
      if (this->room_is_remaining(room_id)) {
        this->place_component(room_id);
        if (this->room_is_remaining(room_id)) {
          throw std::logic_error("room ID present in remaining set after processing");
        }
      }
    }
  }
};

int main(int argc, char** argv) {
  phosg::Arguments args(argv + 1, argc - 1);

  const auto& data_dir = args.get<std::string>(0);
  std::string output_dir = args.get<std::string>(1, false);
  if (output_dir.empty()) {
    output_dir = ".";
  }
  uint8_t overlay_alpha = args.get<uint8_t>("overlay-alpha", 0x80);
  uint8_t annotation_alpha = args.get<uint8_t>("annotation-alpha", 0xFF);
  bool render_basic_graphics = !args.get<bool>("skip-basic-graphics");
  bool render_custom_graphics = !args.get<bool>("skip-custom-graphics");
  bool render_all_components = !args.get<bool>("first-component-only");
  bool save_layers = args.get<bool>("save-layers");
  auto level_nums = args.get_multi<size_t>("level");
  args.assert_none_unused();

  std::unordered_set<size_t> level_nums_set(level_nums.begin(), level_nums.end());

  auto prince_rsrc = ResourceDASM::parse_resource_fork(phosg::load_file(data_dir + "/Prince.rsrc/..namedfork/rsrc"));
  auto level_kind_defs = load_level_kinds(data_dir);

  for (const auto& res_id : prince_rsrc.all_resources_of_type(RESOURCE_TYPE_LEVL)) {
    auto res = prince_rsrc.get_resource(RESOURCE_TYPE_LEVL, res_id);
    if (res->data.size() != sizeof(PrinceOfPersia2Level)) {
      throw std::runtime_error(std::format("invalid LEVL resource with ID {}", res_id));
    }
    const auto* level = reinterpret_cast<const PrinceOfPersia2Level*>(res->data.data());
    if (!level_nums_set.empty() && !level_nums_set.contains(level->level_number)) {
      phosg::log_info_f("Skipping LEVL:{} (level number {})", res_id, level->level_number);
      continue;
    }

    auto& level_kind = level_kind_defs.at(level->level_kind);

    RoomGraph room_graph(level);
    for (const auto& component : room_graph.components) {
      if (component.component_id && !render_all_components) {
        break;
      }

      size_t w_rooms = 0, h_rooms = 0;
      for (const auto& [_, placement] : component.placement_map) {
        w_rooms = std::max<size_t>(placement.first + 1, w_rooms);
        h_rooms = std::max<size_t>(placement.second + 1, h_rooms);
      }

      LevelKind::DrawLayers layers(w_rooms * TILE_W_PIXELS * 10, h_rooms * TILE_H_PIXELS * 3);
      for (const auto& [room_id, placement] : component.placement_map) {
        size_t room_x = placement.first * (TILE_W_PIXELS * 10);
        size_t room_y = placement.second * (TILE_H_PIXELS * 3);
        auto room_layers = layers.view(room_x, room_y, TILE_W_PIXELS * 10, TILE_H_PIXELS * 3);
        room_layers.sky().clear((room_id < level->num_used_rooms) ? 0xFFFFFFFF : 0xE0E0E0FF);
        if (level_kind) {
          level_kind->draw_room(
              room_layers,
              *level,
              room_id,
              render_basic_graphics,
              render_custom_graphics,
              overlay_alpha,
              annotation_alpha);
        }
      }

      phosg::ImageRGBA8888N map(w_rooms * TILE_W_PIXELS * 10, h_rooms * TILE_H_PIXELS * 3);
      map.clear(0x202020FF);
      layers.compose_into(map);

      if (save_layers) {
        for (size_t layer_num = 0; layer_num < layers.layers.size(); layer_num++) {
          const auto& layer = layers.layers[layer_num];
          std::string filename = std::format("{}/pop2_level{}_part{}_layer{}.png", output_dir, res_id, component.component_id, layer_num);
          phosg::save_file(filename, layer.serialize(phosg::ImageFormat::PNG));
          phosg::log_info_f("... {}", filename);
        }
      }
      std::string filename = std::format("{}/pop2_level{}_part{}.png", output_dir, res_id, component.component_id);
      phosg::save_file(filename, map.serialize(phosg::ImageFormat::PNG));
      phosg::log_info_f("... {}", filename);
    }
  }

  return 0;
}
